package com.cryptostrategy.platform.persistence.internal.backtesting;
import com.cryptostrategy.platform.backtesting.api.error.*;import com.cryptostrategy.platform.backtesting.api.model.*;import com.cryptostrategy.platform.backtesting.api.port.out.BacktestResultStore;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;import java.sql.Timestamp;import java.util.*;
public final class JdbcBacktestResultStore implements BacktestResultStore{private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final BacktestJsonMapper json;public JdbcBacktestResultStore(JdbcTemplate jdbc,TransactionTemplate tx,BacktestJsonMapper json){this.jdbc=Objects.requireNonNull(jdbc);this.tx=Objects.requireNonNull(tx);this.json=Objects.requireNonNull(json);}@Override public BacktestResult save(BacktestResult r){return tx.execute(status->{Integer valid=jdbc.queryForObject("select count(*) from experiment.candidate_definition c join experiment.job j on j.candidate_id=c.candidate_id and j.experiment_id=c.experiment_id join experiment.execution_attempt a on a.job_id=j.job_id and a.candidate_id=c.candidate_id where c.candidate_id=? and c.experiment_id=? and j.job_id=? and j.job_type='BACKTEST' and a.attempt_id=? and a.status='SUCCEEDED'",Integer.class,r.candidateId().value(),r.experimentId().value(),r.jobId().value(),r.successfulAttemptId().value());if(valid==null||valid!=1)throw new BacktestException(BacktestErrorCode.INVALID_LINEAGE,"Result lineage is not a successful BACKTEST attempt");List<String> existing=jdbc.query("select result_fingerprint from experiment.backtest_result where candidate_id=?",(rs,n)->rs.getString(1),r.candidateId().value());if(!existing.isEmpty()){if(existing.getFirst().equals(r.fingerprint()))return r;throw new BacktestException(BacktestErrorCode.DUPLICATE_OUTCOME,"Candidate already has a different Result");}var e=r.equityCurveSummary();jdbc.update("insert into experiment.backtest_result(backtest_result_id,experiment_id,candidate_id,job_id,successful_attempt_id,initial_capital,final_capital,total_fees,result_fingerprint,manifest_fingerprint,dataset_fingerprint,strategy_fingerprint,assumptions_version,assumptions_json,equity_point_count,equity_peak,equity_trough,equity_peak_sequence,equity_trough_sequence,equity_curve_fingerprint,completed_at) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?,?,?,?,?,?)",r.resultId().value(),r.experimentId().value(),r.candidateId().value(),r.jobId().value(),r.successfulAttemptId().value(),r.initialCapital().value(),r.finalCapital().value(),r.totalFees().value(),r.fingerprint(),r.provenance().manifestFingerprint(),r.provenance().datasetFingerprint(),r.provenance().strategyFingerprint(),r.assumptions().contractVersion(),json.write(r.assumptions()),e.pointCount(),e.peakEquity().value(),e.troughEquity().value(),e.peakSequence(),e.troughSequence(),e.curveDigest(),Timestamp.from(r.completedAt()));for(Trade t:r.trades())jdbc.update("insert into experiment.trade(trade_id,backtest_result_id,sequence_no,side,entry_time,exit_time,entry_price,exit_price,quantity,entry_fee,exit_fee,fee,profit_loss,post_trade_cash,exit_reason) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",t.tradeId().value(),r.resultId().value(),t.sequence(),"BUY",Timestamp.from(t.entryTime()),Timestamp.from(t.exitTime()),t.entryPrice().value(),t.exitPrice().value(),t.quantity().value(),t.entryFee().value(),t.exitFee().value(),t.totalFee().value(),t.realizedPnl(),t.postTradeCash().value(),t.exitReason().name());return r;});}}
